import re
from decimal import Decimal

_FEE = Decimal('1.50')
_AMOUNT_RE = re.compile(r'^[0-9]+(?:\.[0-9]{1,2})?$')


class InsufficientFunds(Exception):
    pass


class Ledger:
    def __init__(self, overdraft_limit='0.00'):
        self._overdraft_limit = self._parse_amount(overdraft_limit, allow_zero=True)
        self._balance = Decimal('0.00')
        self._history = []

    @staticmethod
    def _parse_amount(amount, allow_zero):
        if not isinstance(amount, str):
            raise TypeError("amount must be a string")
        if not _AMOUNT_RE.fullmatch(amount):
            raise ValueError("amount format is invalid")
        value = Decimal(amount)
        if not allow_zero and value == 0:
            raise ValueError("amount must be non-zero")
        return value

    @staticmethod
    def _format(value):
        value = value.quantize(Decimal('0.01'))
        if value == 0:
            value = Decimal('0.00')
        return f"{value:0.2f}"

    def deposit(self, amount):
        value = self._parse_amount(amount, allow_zero=False)
        self._balance += value
        self._history.append(('deposit', self._format(value)))

    def withdraw(self, amount):
        value = self._parse_amount(amount, allow_zero=False)
        if self._balance - value < -self._overdraft_limit:
            raise InsufficientFunds("withdrawal would exceed overdraft limit")
        self._balance -= value
        self._history.append(('withdraw', self._format(value)))
        if self._balance < 0:
            self._balance -= _FEE
            self._history.append(('fee', self._format(_FEE)))

    def balance(self):
        return self._format(self._balance)

    def history(self):
        return list(self._history)
