def parse_ini(text):
    result = {}
    current = None
    current_section = ''
    current_key = None

    if text == '':
        return result

    for i, raw in enumerate(text.split('\n'), start=1):
        line = raw[:-1] if raw.endswith('\r') else raw

        if line.strip() == '':
            current_key = None
            continue

        if line.lstrip()[:1] in ';#':
            continue

        if line[:1] in ' \t':
            if current_key is None:
                raise ValueError(f"line {i}: continuation line without a key")
            part = line.strip()
            if current[current_key]:
                current[current_key] += ' ' + part
            else:
                current[current_key] = part
            continue

        stripped = line.strip()
        if stripped.startswith('[') and stripped.endswith(']'):
            name = stripped[1:-1].strip().lower()
            current_section = name
            current = result.setdefault(name, {})
            current_key = None
            continue

        if '=' not in line:
            raise ValueError(f"line {i}: expected '=' in key line")

        key_part, val_part = line.split('=', 1)
        key = key_part.strip().lower()
        if key == '':
            raise ValueError(f"line {i}: empty key")

        if current is None:
            current_section = ''
            current = result.setdefault('', {})

        if key in current:
            raise ValueError(f"duplicate key {key!r} in section {current_section!r} at line {i}")

        current[key] = val_part.strip()
        current_key = key

    for section in result.values():
        for k, v in list(section.items()):
            if len(v) >= 2 and v[0] == '"' and v[-1] == '"':
                section[k] = v[1:-1]

    return result
