def render(template, values):
    s = template
    n = len(s)
    out = []
    out_append = out.append

    i = 0
    while i < n:
        c = s[i]
        if c == '\\':
            if i + 1 < n:
                nxt = s[i + 1]
                if nxt == '\\':
                    out_append('\\')
                    i += 2
                    continue
                if nxt == '{' and i + 2 < n and s[i + 2] == '{':
                    out_append('{{')
                    i += 3
                    continue
            out_append('\\')
            i += 1
        elif c == '{':
            if i + 1 < n and s[i + 1] == '{':
                j = s.find('}}', i + 2)
                if j < 0:
                    raise ValueError(f"unclosed placeholder at {i}")
                content = s[i + 2:j]
                pipe = content.find('|')
                if pipe < 0:
                    key_part = content
                    has_default = False
                    default_part = ''
                else:
                    key_part = content[:pipe]
                    has_default = True
                    default_part = content[pipe + 1:]
                key = key_part.strip(' ')
                if not _is_valid_key(key):
                    raise ValueError(f"bad key: {key}")
                val = _lookup(values, key)
                if val is None:
                    if has_default:
                        out_append(default_part.strip(' '))
                    else:
                        raise KeyError(f"missing: {key}")
                else:
                    out_append(_format_value(val))
                i = j + 2
            else:
                out_append('{')
                i += 1
        elif c == '}':
            out_append('}')
            i += 1
        else:
            nxt = n
            k = s.find('\\', i)
            if k != -1 and k < nxt:
                nxt = k
            k = s.find('{', i)
            if k != -1 and k < nxt:
                nxt = k
            k = s.find('}', i)
            if k != -1 and k < nxt:
                nxt = k
            out_append(s[i:nxt])
            i = nxt
    return ''.join(out)


def _is_valid_key(key):
    m = len(key)
    if m == 0:
        return False
    i = 0
    while True:
        c = key[i]
        if not (('a' <= c <= 'z') or ('A' <= c <= 'Z') or c == '_'):
            return False
        i += 1
        while i < m and key[i] != '.':
            c = key[i]
            if not (('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9') or c == '_'):
                return False
            i += 1
        if i == m:
            return True
        i += 1
        if i == m:
            return False


def _lookup(values, key):
    parts = key.split('.')
    cur = values
    for p in parts:
        if not isinstance(cur, dict) or p not in cur:
            return None
        cur = cur[p]
    if cur is None:
        return None
    return cur


def _format_value(v):
    if v is True:
        return 'true'
    if v is False:
        return 'false'
    return str(v)
