def wrap_text(text, width):
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an int >= 2")
    words = text.split()
    if not words:
        return []
    lines = []
    current = ""
    chunk_len = width - 1
    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""
            start = 0
            while len(word) - start > width:
                lines.append(word[start:start + chunk_len] + "-")
                start += chunk_len
            current = word[start:]
        else:
            if current:
                if len(current) + 1 + len(word) <= width:
                    current += " " + word
                else:
                    lines.append(current)
                    current = word
            else:
                current = word
    if current:
        lines.append(current)
    return lines
