import heapq
from typing import Iterable, List, Tuple, Set, Dict


class CycleError(ValueError):
    def __init__(self, nodes: Iterable[str]):
        self.nodes = sorted(nodes)
        super().__init__(f"cycle detected; cannot place: {self.nodes}")


def _build_graph(nodes: Iterable[str], edges: List[Tuple[str, str]]):
    node_set = set(nodes)
    adjacency: Dict[str, Set[str]] = {n: set() for n in node_set}
    indegree: Dict[str, int] = {n: 0 for n in node_set}
    seen_edges: Set[Tuple[str, str]] = set()

    for edge in edges:
        before, after = edge
        if before not in node_set:
            raise ValueError(f"unknown node: {before!r}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after!r}")
        key = (before, after)
        if key in seen_edges:
            continue
        seen_edges.add(key)
        adjacency[before].add(after)
        indegree[after] += 1

    return node_set, adjacency, indegree


def topo_order(nodes: Iterable[str], edges: List[Tuple[str, str]]) -> List[str]:
    node_set, adjacency, indegree = _build_graph(nodes, edges)

    heap = [n for n in node_set if indegree[n] == 0]
    heapq.heapify(heap)

    order: List[str] = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in adjacency[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)

    if len(order) != len(node_set):
        raise CycleError(node_set - set(order))

    return order


def layers(nodes: Iterable[str], edges: List[Tuple[str, str]]) -> List[List[str]]:
    node_set, adjacency, indegree = _build_graph(nodes, edges)

    remaining = set(node_set)
    current = sorted(n for n in node_set if indegree[n] == 0)
    result: List[List[str]] = []

    while current:
        result.append(current)
        next_layer: Set[str] = set()
        for n in current:
            remaining.remove(n)
            for m in adjacency[n]:
                indegree[m] -= 1
                if indegree[m] == 0:
                    next_layer.add(m)
        current = sorted(next_layer)

    if remaining:
        raise CycleError(remaining)

    return result
