        return True
    if isinstance(x, bool):
        return False
    return isinstance(x, (int, float))


def spans(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [0] * n
    stack = []
    last_none = -1
    for i, p in enumerate(prices):
        if p is None:
            last_none = i
            stack.clear()
            continue
        if not _is_valid_price(p):
            raise TypeError("prices elements must be int, float or None")
        while stack and prices[stack[-1]] <= p:
            stack.pop()
        if stack:
            result[i] = i - stack[-1]
        else:
            result[i] = i - last_none
        stack.append(i)
    return result


def next_greater(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [-1] * n
    stack = []
    for i in range(n - 1, -1, -1):
        p = prices[i]
        if p is None:
            stack.clear()
            continue
        if not _is_valid_price(p):
            raise TypeError("prices elements must be int, float or None")
        while stack and prices[stack[-1]] <= p:
            stack.pop()
        if stack:
            result[i] = stack[-1]
        stack.append(i)
    return result


def widest_span(prices):
    span_list = spans(prices)
    best_idx = -1
    best_span = 0
    for i, s in enumerate(span_list):
        if s > best_span or (s == best_span and i > best_idx):
            best_idx = i
            best_span = s
    return (best_idx, best_span)
