def _parse_int(token: str) -> int:
    if not token:
        raise ValueError("invalid cron: missing number")
    for ch in token:
        if ch < "0" or ch > "9":
            raise ValueError("invalid cron: number must contain ASCII digits only")
    return int(token)


def _split_expr(expr: str) -> tuple[str, str]:
    parts = expr.split()
    if len(parts) != 2:
        raise ValueError("invalid cron: expression must contain exactly two fields")
    return parts[0], parts[1]


def expand_field(field: str, lo: int, hi: int) -> list[int]:
    if field == "":
        raise ValueError("invalid cron: empty field")

    values: set[int] = set()

    for item in field.split(","):
        if item == "":
            raise ValueError("invalid cron: empty item")

        if "/" in item:
            base, step_str = item.split("/", 1)
            if step_str == "":
                raise ValueError("invalid cron: missing step")
            step = _parse_int(step_str)
            if step == 0:
                raise ValueError("invalid cron: step must be >= 1")
        else:
            base = item
            step = 1

        if base == "":
            raise ValueError("invalid cron: empty base")

        if "-" in base:
            a_str, b_str = base.split("-", 1)
            a = _parse_int(a_str)
            b = _parse_int(b_str)
            if a > b:
                raise ValueError("invalid cron: range start greater than end")
            start, end = a, b
        elif base == "*":
            start, end = lo, hi
        else:
            n = _parse_int(base)
            if step == 1:
                start, end = n, n
            else:
                start, end = n, hi

        if start < lo or end > hi:
            raise ValueError("invalid cron: value out of range")

        value = start
        while value <= end:
            values.add(value)
            value += step

    return sorted(values)


def cron_matches(expr: str, hour: int, minute: int) -> bool:
    minute_field, hour_field = _split_expr(expr)
    minute_values = set(expand_field(minute_field, 0, 59))
    hour_values = set(expand_field(hour_field, 0, 23))
    return hour in hour_values and minute in minute_values


def next_match(expr: str, hour: int, minute: int) -> tuple[int, int]:
    minute_field, hour_field = _split_expr(expr)
    minute_values = set(expand_field(minute_field, 0, 59))
    hour_values = set(expand_field(hour_field, 0, 23))

    current = hour * 60 + minute
    for offset in range(1, 1441):
        total = current + offset
        nh = (total // 60) % 24
        nm = total % 60
        if nh in hour_values and nm in minute_values:
            return (nh, nm)

    raise ValueError("invalid cron: expression matches no time")
