import re
from collections import deque
from decimal import Decimal

_PRICE_RE = re.compile(r'^[0-9]+(?:\.[0-9]{1,4})?$')


def _validate_qty(qty):
    if not isinstance(qty, int) or isinstance(qty, bool):
        raise TypeError("qty must be int")
    if qty <= 0:
        raise ValueError("qty must be positive")


def _parse_price(price):
    if not isinstance(price, str):
        raise TypeError("price must be str")
    if not _PRICE_RE.fullmatch(price):
        raise ValueError("invalid price format")
    if '.' in price:
        int_part, frac = price.split('.')
        frac = (frac + '0000')[:4]
    else:
        int_part, frac = price, '0000'
    return int(int_part + frac)


def _round_to_100(n):
    q, r = divmod(n, 100)
    if r < 50:
        return q * 100
    if r > 50:
        return (q + 1) * 100
    if q & 1:
        return (q + 1) * 100
    return q * 100


class FifoBook:
    __slots__ = ('_lots', '_holdings', '_cost_units', '_realized_cents')

    def __init__(self):
        self._lots = deque()
        self._holdings = 0
        self._cost_units = 0
        self._realized_cents = 0

    def buy(self, qty, price):
        _validate_qty(qty)
        price_units = _parse_price(price)
        self._lots.append((qty, price, price_units))
        self._holdings += qty
        self._cost_units += qty * price_units

    def sell(self, qty, price):
        _validate_qty(qty)
        if qty > self._holdings:
            raise ValueError("insufficient holdings")
        sell_units = _parse_price(price)
        remaining = qty
        total_pnl_units = 0
        while remaining > 0:
            lot_qty, lot_price_str, lot_units = self._lots[0]
            if lot_qty <= remaining:
                consumed = lot_qty
                self._lots.popleft()
            else:
                consumed = remaining
                self._lots[0] = (lot_qty - consumed, lot_price_str, lot_units)
            total_pnl_units += (sell_units - lot_units) * consumed
            self._holdings -= consumed
            self._cost_units -= lot_units * consumed
            remaining -= consumed
        rounded = _round_to_100(total_pnl_units)
        pnl_cents = rounded // 100
        self._realized_cents += pnl_cents
        return Decimal(pnl_cents).scaleb(-2)

    def realized(self):
        return Decimal(self._realized_cents).scaleb(-2)

    def holdings(self):
        return self._holdings

    def lots(self):
        return [(qty, price_str) for qty, price_str, _ in self._lots]

    def cost_basis(self):
        rounded = _round_to_100(self._cost_units)
        return Decimal(rounded // 100).scaleb(-2)
