import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r'[vV]?'
    r'(0|[1-9]\d*)\.'
    r'(0|[1-9]\d*)\.'
    r'(0|[1-9]\d*)'
    r'(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?'
    r'(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?'
)


def parse_version(text):
    if not isinstance(text, str):
        raise ValueError('invalid version: input must be a string')
    match = _VERSION_RE.fullmatch(text)
    if not match:
        raise ValueError(f'invalid version: {text}')
    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    pre_raw = match.group(4)
    build = match.group(5)
    prerelease = ()
    if pre_raw is not None:
        parts = []
        for part in pre_raw.split('.'):
            if part.isdigit():
                if len(part) > 1 and part[0] == '0':
                    raise ValueError(f'invalid version: {text}')
                parts.append(int(part))
            else:
                parts.append(part)
        prerelease = tuple(parts)
    return (major, minor, patch, prerelease, build)


def _compare_prerelease(a, b):
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    for x, y in zip(a, b):
        x_num = isinstance(x, int)
        y_num = isinstance(y, int)
        if x_num and y_num:
            if x < y:
                return -1
            if x > y:
                return 1
        elif x_num:
            return -1
        elif y_num:
            return 1
        else:
            if x < y:
                return -1
            if x > y:
                return 1
    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1
    return 0


def compare_versions(a, b):
    ta = parse_version(a)
    tb = parse_version(b)
    for i in range(3):
        if ta[i] < tb[i]:
            return -1
        if ta[i] > tb[i]:
            return 1
    return _compare_prerelease(ta[3], tb[3])


def sort_versions(versions):
    return sorted(versions, key=cmp_to_key(compare_versions))
