import heapq
from typing import List, Tuple


def _validate(meetings, k):
    if type(k) is not int:
        raise ValueError("k must be an int")
    if k < 1:
        raise ValueError("k must be >= 1")
    if not isinstance(meetings, list):
        raise ValueError("meetings must be a list")
    for meeting in meetings:
        if not isinstance(meeting, (list, tuple)) or len(meeting) != 2:
            raise ValueError("each meeting must be a (start, end) pair")
        start, end = meeting
        if type(start) is not int or type(end) is not int:
            raise ValueError("start and end must be ints")
        if start >= end:
            raise ValueError("start must be < end")


def _allocate(meetings: List[Tuple[int, int]], k: int):
    n = len(meetings)
    result: List[Tuple[int, int, int] | None] = [None] * n
    counts = [0] * k

    available = list(range(k))
    heapq.heapify(available)
    busy: List[Tuple[int, int]] = []

    indexed = sorted(enumerate(meetings), key=lambda item: (item[1][0], item[0]))

    for idx, (start, end) in indexed:
        duration = end - start
        while busy and busy[0][0] <= start:
            release, room = heapq.heappop(busy)
            heapq.heappush(available, room)
        if available:
            room = heapq.heappop(available)
            actual_start = start
        else:
            release, room = heapq.heappop(busy)
            actual_start = release
        actual_end = actual_start + duration
        result[idx] = (room, actual_start, actual_end)
        counts[room] += 1
        heapq.heappush(busy, (actual_end, room))

    return result, counts


def assign_rooms(meetings: List[Tuple[int, int]], k: int) -> List[Tuple[int, int, int]]:
    _validate(meetings, k)
    if not meetings:
        return []
    result, _ = _allocate(meetings, k)
    return result


def busiest_room(meetings: List[Tuple[int, int]], k: int) -> int:
    _validate(meetings, k)
    if not meetings:
        return 0
    _, counts = _allocate(meetings, k)
    max_count = max(counts)
    return counts.index(max_count)
