import heapq
from collections import Counter


class MedianTracker:
    def __init__(self, prefer_high=False):
        self.prefer_high = prefer_high
        self.lower = []
        self.upper = []
        self.lower_size = 0
        self.upper_size = 0
        self.size = 0
        self.delayed = Counter()
        self.counts = Counter()

    def _prune_lower(self):
        while self.lower:
            v = -self.lower[0]
            if self.delayed[v]:
                heapq.heappop(self.lower)
                self.delayed[v] -= 1
                if not self.delayed[v]:
                    del self.delayed[v]
            else:
                break

    def _prune_upper(self):
        while self.upper:
            v = self.upper[0]
            if self.delayed[v]:
                heapq.heappop(self.upper)
                self.delayed[v] -= 1
                if not self.delayed[v]:
                    del self.delayed[v]
            else:
                break

    def _balance(self):
        if self.prefer_high:
            if self.upper_size > self.lower_size + 1:
                self._prune_upper()
                v = heapq.heappop(self.upper)
                self.upper_size -= 1
                heapq.heappush(self.lower, -v)
                self.lower_size += 1
            elif self.lower_size > self.upper_size:
                self._prune_lower()
                v = -heapq.heappop(self.lower)
                self.lower_size -= 1
                heapq.heappush(self.upper, v)
                self.upper_size += 1
        else:
            if self.lower_size > self.upper_size + 1:
                self._prune_lower()
                v = -heapq.heappop(self.lower)
                self.lower_size -= 1
                heapq.heappush(self.upper, v)
                self.upper_size += 1
            elif self.upper_size > self.lower_size:
                self._prune_upper()
                v = heapq.heappop(self.upper)
                self.upper_size -= 1
                heapq.heappush(self.lower, -v)
                self.lower_size += 1

    def add(self, x):
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("only int values are allowed")
        self.counts[x] += 1
        self.size += 1
        if self.prefer_high:
            self._prune_upper()
            if not self.upper or x >= self.upper[0]:
                heapq.heappush(self.upper, x)
                self.upper_size += 1
            else:
                heapq.heappush(self.lower, -x)
                self.lower_size += 1
        else:
            self._prune_lower()
            if not self.lower or x <= -self.lower[0]:
                heapq.heappush(self.lower, -x)
                self.lower_size += 1
            else:
                heapq.heappush(self.upper, x)
                self.upper_size += 1
        self._balance()

    def remove(self, x):
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("only int values are allowed")
        if self.counts[x] == 0:
            raise ValueError("not present: {}".format(x))
        self.counts[x] -= 1
        self.size -= 1
        if self.prefer_high:
            self._prune_upper()
            if x >= self.upper[0]:
                self.upper_size -= 1
                self.delayed[x] += 1
            else:
                self.lower_size -= 1
                self.delayed[x] += 1
        else:
            self._prune_lower()
            if x <= -self.lower[0]:
                self.lower_size -= 1
                self.delayed[x] += 1
            else:
                self.upper_size -= 1
                self.delayed[x] += 1
        self._balance()

    def median(self):
        if self.size == 0:
            raise LookupError("median is undefined for empty tracker")
        if self.prefer_high:
            self._prune_upper()
            return self.upper[0]
        else:
            self._prune_lower()
            return -self.lower[0]

    def __len__(self):
        return self.size
