def merge(intervals):
    cleaned = []
    for iv in intervals:
        start, end = iv
        if start > end:
            raise ValueError(f"interval start greater than end: {iv!r}")
        if start == end:
            continue
        cleaned.append((start, end))
    if not cleaned:
        return []
    cleaned.sort(key=lambda x: x[0])
    merged = [cleaned[0]]
    for start, end in cleaned[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged


def subtract(a, b):
    a_merged = merge(a)
    b_merged = merge(b)
    result = []
    j = 0
    n = len(b_merged)
    for a_start, a_end in a_merged:
        cur_start, cur_end = a_start, a_end
        while j < n and b_merged[j][1] <= cur_start:
            j += 1
        while j < n and b_merged[j][0] < cur_end:
            b_start, b_end = b_merged[j]
            if b_start > cur_start:
                result.append((cur_start, b_start))
            if b_end < cur_end:
                cur_start = b_end
                j += 1
            else:
                cur_start = cur_end
                break
        if cur_start < cur_end:
            result.append((cur_start, cur_end))
    return result


def total_length(intervals):
    return sum(end - start for start, end in merge(intervals))
