def validate_stream(events):
    events = list(events)
    seen = set()
    for event in events:
        eid = event[1]
        if eid in seen:
            raise ValueError(f"duplicate id: {eid!r}")
        seen.add(eid)

    prev = None
    for event in events:
        ts, eid, _payload = event
        key = (ts, eid)
        if prev is not None and not (prev < key):
            raise ValueError(f"unsorted: {prev!r} not before {key!r}")
        prev = key

    return None


def diff_events(old, new):
    validate_stream(old)
    validate_stream(new)

    old_by_id = {eid: (ts, payload) for ts, eid, payload in old}
    new_by_id = {eid: (ts, payload) for ts, eid, payload in new}

    old_ids = set(old_by_id)
    new_ids = set(new_by_id)

    added = [eid for _ts, eid, _payload in new if eid not in old_ids]
    removed = [eid for _ts, eid, _payload in old if eid not in new_ids]

    moved = []
    changed = []
    for ts, eid, payload in new:
        if eid in old_ids:
            old_ts, old_payload = old_by_id[eid]
            if old_ts != ts:
                moved.append(eid)
            if old_payload != payload:
                changed.append(eid)

    return {
        "added": added,
        "removed": removed,
        "moved": moved,
        "changed": changed,
    }


def merge_streams(a, b):
    validate_stream(a)
    validate_stream(b)

    combined = {}
    for ts, eid, payload in a:
        combined[eid] = (ts, eid, payload)
    for ts, eid, payload in b:
        combined[eid] = (ts, eid, payload)

    return sorted(combined.values(), key=lambda event: (event[0], event[1]))
