import copy
from typing import Any


def escape_token(token: str) -> str:
    return token.replace("~", "~0").replace("/", "~1")


def _decode_token(token: str) -> str:
    out = []
    i = 0
    n = len(token)
    while i < n:
        ch = token[i]
        if ch == "~":
            if i + 1 >= n:
                raise ValueError("Invalid escape at end of token")
            nxt = token[i + 1]
            if nxt == "0":
                out.append("~")
            elif nxt == "1":
                out.append("/")
            else:
                raise ValueError(f"Invalid escape '~{nxt}'")
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def _parse_pointer(pointer: str) -> list[str]:
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("Non-empty pointer must start with '/'")
    raw_tokens = pointer[1:].split("/")
    return [_decode_token(t) for t in raw_tokens]


def _list_index(token: str, length: int, *, allow_end: bool = False, allow_dash: bool = False) -> int:
    if allow_dash and token == "-":
        return length
    if token == "0":
        idx = 0
    else:
        if not token or token[0] == "0" or not all("0" <= ch <= "9" for ch in token):
            raise KeyError(token)
        idx = int(token)
    if allow_end:
        if idx > length:
            raise KeyError(token)
    else:
        if idx >= length:
            raise KeyError(token)
    return idx


def resolve(doc: Any, pointer: str) -> Any:
    tokens = _parse_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            try:
                current = current[token]
            except KeyError:
                raise KeyError(token)
        elif isinstance(current, list):
            idx = _list_index(token, len(current), allow_end=False, allow_dash=False)
            current = current[idx]
        else:
            raise KeyError(token)
    return current


def set_value(doc: Any, pointer: str, value: Any) -> Any:
    tokens = _parse_pointer(pointer)
    if not tokens:
        return value
    new_doc = copy.deepcopy(doc)
    parent = new_doc
    for token in tokens[:-1]:
        if isinstance(parent, dict):
            try:
                parent = parent[token]
            except KeyError:
                raise KeyError(token)
        elif isinstance(parent, list):
            idx = _list_index(token, len(parent), allow_end=False, allow_dash=False)
            parent = parent[idx]
        else:
            raise KeyError(token)
    last = tokens[-1]
    if isinstance(parent, dict):
        parent[last] = value
    elif isinstance(parent, list):
        idx = _list_index(last, len(parent), allow_end=True, allow_dash=True)
        if idx == len(parent):
            parent.append(value)
        else:
            parent[idx] = value
    else:
        raise KeyError(last)
    return new_doc


__all__ = ["resolve", "set_value", "escape_token"]
