class Scheduler:
    def __init__(self):
        self._tasks = {}
        self._completed = set()
        self._order_counter = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")

        dependencies = tuple(after)
        for dep in dependencies:
            if dep not in self._tasks:
                raise KeyError(dep)

        self._tasks[name] = {
            "priority": priority,
            "dependencies": dependencies,
            "order": self._order_counter,
            "state": "pending",
        }
        self._order_counter += 1

    def next(self):
        ready = []
        for name, info in self._tasks.items():
            if info["state"] != "pending":
                continue
            if all(dep in self._completed for dep in info["dependencies"]):
                ready.append((info["priority"], info["order"], name))

        if not ready:
            return None

        _, _, name = max(ready, key=lambda item: (item[0], -item[1]))
        self._tasks[name]["state"] = "running"
        return name

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(name)

        if self._tasks[name]["state"] != "running":
            raise ValueError(f"Task {name!r} is not running")

        self._tasks[name]["state"] = "completed"
        self._completed.add(name)

    def remaining(self):
        return sum(1 for info in self._tasks.values() if info["state"] != "completed")
