from bisect import bisect_right

__all__ = ["best_schedule", "max_parallel"]


def _validate_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list of 3-tuples")
    for i, interval in enumerate(intervals):
        if not isinstance(interval, tuple) or len(interval) != 3:
            raise TypeError(f"intervals[{i}] must be a 3-tuple")
        start, end, weight = interval
        for name, value in (("start", start), ("end", end), ("weight", weight)):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(f"{name} of intervals[{i}] must be int")
        if start >= end:
            raise ValueError(f"start must be less than end for intervals[{i}]")


def best_schedule(intervals):
    _validate_intervals(intervals)

    # Non-positive weights can never belong to an optimal schedule.
    candidates = [(s, e, w) for s, e, w in intervals if w > 0]
    if not candidates:
        return (0, 0)

    candidates.sort(key=lambda x: x[1])

    ends = []
    # dp[i] = (maximum total weight, fewest interval count) using first i candidates.
    dp = [(0, 0)]

    for s, e, w in candidates:
        p = bisect_right(ends, s)
        cand_weight = dp[p][0] + w
        cand_count = dp[p][1] + 1
        prev_weight, prev_count = dp[-1]

        if cand_weight > prev_weight or (
            cand_weight == prev_weight and cand_count < prev_count
        ):
            dp.append((cand_weight, cand_count))
        else:
            dp.append((prev_weight, prev_count))

        ends.append(e)

    return dp[-1]


def max_parallel(intervals):
    _validate_intervals(intervals)

    events = []
    for s, e, _ in intervals:
        events.append((s, 1))
        events.append((e, -1))

    events.sort()

    current = 0
    maximum = 0
    for _, delta in events:
        current += delta
        if current > maximum:
            maximum = current

    return maximum
