        raise TypeError("n must be an int")
    if n < 1 or n > 3999:
        raise ValueError("n out of range")
    parts = []
    for value, numeral in _ROMAN_MAP:
        while n >= value:
            parts.append(numeral)
            n -= value
    return "".join(parts)


def from_roman(s):
