def _parse_version(s):
    s = s.strip()
    if not s:
        raise ValueError("empty version string")
    parts = s.split(".")
    result = []
    for part in parts:
        if not part or not all("0" <= c <= "9" for c in part):
            raise ValueError(f"invalid version component {part!r}")
        result.append(int(part))
    return result


def _compare_versions(a, b):
    n = max(len(a), len(b))
    for i in range(n):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1
    return 0


def _parse_spec(spec):
    spec = spec.strip()
    if not spec:
        return []
    clauses = []
    for raw in spec.split(","):
        clause = raw.strip()
        if not clause:
            raise ValueError("empty spec clause")
        op = None
        for candidate in ("==", "!=", ">=", "<=", "~=", ">", "<"):
            if clause.startswith(candidate):
                op = candidate
                break
        if op is None:
            raise ValueError(f"missing operator in clause {clause!r}")
        version_str = clause[len(op):].strip()
        if not version_str:
            raise ValueError(f"missing version in clause {clause!r}")
        version = _parse_version(version_str)
        if op == "~=":
            if len(version) < 2:
                raise ValueError("~= requires a version with at least two components")
            upper = list(version[:-1])
            upper[-1] += 1
            clauses.append((">=", version))
            clauses.append(("<", upper))
        else:
            clauses.append((op, version))
    return clauses


def _check_clause(version, op, target):
    cmp = _compare_versions(version, target)
    if op == "==":
        return cmp == 0
    if op == "!=":
        return cmp != 0
    if op == ">=":
        return cmp >= 0
    if op == "<=":
        return cmp <= 0
    if op == ">":
        return cmp > 0
    if op == "<":
        return cmp < 0
    raise ValueError(f"unknown operator {op!r}")


def satisfies(version, spec):
    v = _parse_version(version)
    for op, target in _parse_spec(spec):
        if not _check_clause(v, op, target):
            return False
    return True


def max_satisfying(versions, spec):
    clauses = _parse_spec(spec)
    best = None
    best_index = None
    for i, s in enumerate(versions):
        v = _parse_version(s)
        satisfied = True
        for op, target in clauses:
            if not _check_clause(v, op, target):
                satisfied = False
                break
        if satisfied:
            if best is None or _compare_versions(v, best) > 0:
                best = v
                best_index = i
    if best is None:
        return None
    return versions[best_index]
