import math
from collections import deque

__all__ = ["longest_calm", "count_calm"]


def _validate_limit(limit):
    if isinstance(limit, bool) or not isinstance(limit, (int, float)):
        raise ValueError("limit must be an int or float that is >= 0 and not NaN")
    if limit < 0 or limit != limit:
        raise ValueError("limit must be non-negative and not NaN")


def _validate_value(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("every element of values must be an int or float")
    if isinstance(value, float) and math.isnan(value):
        raise ValueError("values must not contain NaN")


def longest_calm(values, limit):
    _validate_limit(limit)

    best_i = 0
    best_j = 0
    left = 0
    min_deque = deque()
    max_deque = deque()

    for right, value in enumerate(values):
        _validate_value(value)

        while min_deque and values[min_deque[-1]] >= value:
            min_deque.pop()
        min_deque.append(right)

        while max_deque and values[max_deque[-1]] <= value:
            max_deque.pop()
        max_deque.append(right)

        while values[max_deque[0]] - values[min_deque[0]] > limit:
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        length = right - left + 1
        if length > best_j - best_i:
            best_i = left
            best_j = right + 1

    return (best_i, best_j)


def count_calm(values, limit):
    _validate_limit(limit)

    total = 0
    left = 0
    min_deque = deque()
    max_deque = deque()

    for right, value in enumerate(values):
        _validate_value(value)

        while min_deque and values[min_deque[-1]] >= value:
            min_deque.pop()
        min_deque.append(right)

        while max_deque and values[max_deque[-1]] <= value:
            max_deque.pop()
        max_deque.append(right)

        while values[max_deque[0]] - values[min_deque[0]] > limit:
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        total += right - left + 1

    return total
