import re


def glob_to_regex(pattern: str) -> str:
    i = 0
    n = len(pattern)
    parts = []

    while i < n:
        ch = pattern[i]
        if ch == "*":
            j = i
            while j < n and pattern[j] == "*":
                j += 1
            run_len = j - i

            is_globstar = (
                run_len >= 2
                and (i == 0 or pattern[i - 1] == "/")
                and (i + 2 == n or pattern[i + 2] == "/")
            )

            if is_globstar:
                if i + 2 < n and pattern[i + 2] == "/":
                    # **/  -> zero or more whole segments, each ending in '/'
                    parts.append(r"(?:[^/]+/)*")
                    i += 3
                else:
                    # trailing ** -> any remaining text, including '/' and empty
                    parts.append(r"(?s:.*)")
                    i += 2
            else:
                parts.append(r"[^/]*")
                i = j
        elif ch == "?":
            parts.append(r"[^/]")
            i += 1
        elif ch == "[":
            # find matching ']', respecting backslash escapes
            k = i + 1
            found = False
            while k < n:
                if pattern[k] == "\\":
                    k += 2
                elif pattern[k] == "]":
                    found = True
                    break
                else:
                    k += 1

            if found:
                parts.append(_class_to_regex(pattern[i + 1 : k]))
                i = k + 1
            else:
                parts.append(re.escape("["))
                i += 1
        elif ch == "\\":
            if i + 1 < n:
                parts.append(re.escape(pattern[i + 1]))
                i += 2
            else:
                parts.append(re.escape("\\"))
                i += 1
        else:
            parts.append(re.escape(ch))
            i += 1

    return "".join(parts)


def glob_match(pattern: str, path: str) -> bool:
    return re.fullmatch(glob_to_regex(pattern), path) is not None


def _class_to_regex(content: str) -> str:
    negated = False
    if content.startswith("!"):
        negated = True
        s = content[1:]
    else:
        s = content

    intervals = []
    last_cp = None
    i = 0

    if s.startswith("]"):
        intervals.append((ord("]"), ord("]")))
        last_cp = ord("]")
        i = 1

    while i < len(s):
        c = s[i]
        if c == "\\":
            if i + 1 < len(s):
                cp = ord(s[i + 1])
                intervals.append((cp, cp))
                last_cp = cp
                i += 2
            else:
                cp = ord("\\")
                intervals.append((cp, cp))
                last_cp = cp
                i += 1
        elif c == "-":
            if i == 0 or i == len(s) - 1 or last_cp is None:
                intervals.append((ord("-"), ord("-")))
                last_cp = None
                i += 1
            else:
                nxt = s[i + 1]
                nxt_cp = ord(nxt)
                # a '-' at the end of the class is literal, so a range ending in
                # a trailing '-' is not a range
                if nxt == "-" and i + 1 == len(s) - 1:
                    intervals.append((ord("-"), ord("-")))
                    last_cp = None
                    i += 1
                elif nxt_cp >= last_cp:
                    intervals.append((last_cp, nxt_cp))
                    last_cp = nxt_cp
                    i += 2
                else:
                    intervals.append((ord("-"), ord("-")))
                    last_cp = None
                    i += 1
        else:
            cp = ord(c)
            intervals.append((cp, cp))
            last_cp = cp
            i += 1

    intervals.sort()
    merged = []
    for a, b in intervals:
        if not merged or a > merged[-1][1] + 1:
            merged.append([a, b])
        else:
            merged[-1][1] = max(merged[-1][1], b)

    if negated:
        disallowed = list(merged)
        disallowed.append((ord("/"), ord("/")))
        disallowed.sort()
        dmerged = []
        for a, b in disallowed:
            if not dmerged or a > dmerged[-1][1] + 1:
                dmerged.append([a, b])
            else:
                dmerged[-1][1] = max(dmerged[-1][1], b)
        if not dmerged:
            return "(?!)"
        return "[^" + _intervals_to_class_body(dmerged) + "]"
    else:
        positive = []
        slash = ord("/")
        for a, b in merged:
            if a <= slash <= b:
                if a < slash:
                    positive.append([a, slash - 1])
                if slash + 1 <= b:
                    positive.append([slash + 1, b])
            else:
                positive.append([a, b])
        if not positive:
            return "(?!)"
        return "[" + _intervals_to_class_body(positive) + "]"


def _intervals_to_class_body(intervals: list[list[int]]) -> str:
    body = []
    for a, b in intervals:
        if a == b:
            body.append(_escape_class_char(chr(a)))
        else:
            body.append(_escape_class_char(chr(a)))
            body.append("-")
            body.append(_escape_class_char(chr(b)))
    return "".join(body)


def _escape_class_char(c: str) -> str:
    if c in "]\\^-":
        return "\\" + c
    return c
